package ai.unifiedprocess.petclinic.vet.domain;

import org.jooq.DSLContext;
import org.jooq.Record1;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.util.stream.Stream;

import static ai.unifiedprocess.demo.petclinic.database.Tables.SPECIALTIES;
import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
import static org.jooq.Records.mapping;
import static org.jooq.impl.DSL.multiset;
import static org.jooq.impl.DSL.select;

/** Reads veterinarians with their specialties for UC-002. */
@Repository
@Transactional(readOnly = true)
public class VeterinarianRepository {

    private final DSLContext dsl;

    public VeterinarianRepository(DSLContext dsl) {
        this.dsl = dsl;
    }

    public Stream<Veterinarian> findPage(int offset, int limit) {
        return dsl.select(
                        VETS.FIRST_NAME,
                        VETS.LAST_NAME,
                        multiset(select(SPECIALTIES.NAME)
                                .from(VET_SPECIALTIES)
                                .join(SPECIALTIES).on(SPECIALTIES.ID.eq(VET_SPECIALTIES.SPECIALTY_ID))
                                .where(VET_SPECIALTIES.VET_ID.eq(VETS.ID))
                                .orderBy(SPECIALTIES.NAME.asc()))
                                .convertFrom(records -> records.map(Record1::value1)))
                .from(VETS)
                .orderBy(VETS.LAST_NAME.asc(), VETS.FIRST_NAME.asc(), VETS.ID.asc())
                .offset(offset)
                .limit(limit)
                .fetchStream(mapping(Veterinarian::new));
    }

    public int count() {
        return dsl.fetchCount(VETS);
    }
}
package ai.unifiedprocess.petclinic.vet.ui;

import ai.unifiedprocess.petclinic.core.ui.MainLayout;
import ai.unifiedprocess.petclinic.vet.domain.Veterinarian;
import ai.unifiedprocess.petclinic.vet.domain.VeterinarianRepository;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.data.provider.DataProvider;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;
import com.vaadin.flow.theme.lumo.LumoUtility;

/** UC-002: View Veterinarians. */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VeterinariansView extends VerticalLayout {

    private final transient VeterinarianRepository veterinarianRepository;

    public VeterinariansView(VeterinarianRepository veterinarianRepository) {
        this.veterinarianRepository = veterinarianRepository;
        setSizeFull();
        addClassNames(LumoUtility.Padding.MEDIUM);

        Grid<Veterinarian> grid = new Grid<>();
        grid.setSizeFull();
        grid.addColumn(Veterinarian::firstName).setHeader("First name").setKey("firstName");
        grid.addColumn(Veterinarian::lastName).setHeader("Last name").setKey("lastName");
        grid.addColumn(veterinarian -> veterinarian.specialties().isEmpty()
                        ? "none"
                        : String.join(", ", veterinarian.specialties()))
                .setHeader("Specialties").setKey("specialties");
        grid.setDataProvider(DataProvider.fromCallbacks(
                query -> this.veterinarianRepository.findPage(query.getOffset(), query.getLimit()),
                query -> this.veterinarianRepository.count()));
        add(grid);
    }
}
